  if (ses.length) lines.push(`Latest session ranges: ${ses.join('; ')}.`);
  if (r.liquidity.above.length) lines.push(`Untouched buy-side liquidity above: ${r.liquidity.above.slice(0, 4).map((p) => `${p.label} ${f(p.price)}`).join('; ')}.`);
